canvas.addEventListener('pointerdown',e=>{if(e.button!==0||state.busy)return;const b=canvas.getBoundingClientRect();if(state.mode==='peel'&&state.phase===1){const id=hitPatch(e.clientX,e.clientY);if(id===null)return;if(state.peeled.has(id)){$('stage-label').textContent='이미 벗긴 곳이에요. 돌려서 다른 껍질을 찾아보세요.';return;}pointer={kind:'peel',id,startX:e.clientX-b.left,startY:e.clientY-b.top,x:e.clientX-b.left,y:e.clientY-b.top};}else pointer={kind:'rotate',lastX:e.clientX};canvas.setPointerCapture(e.pointerId);requestDraw();});
canvas.addEventListener('pointermove',e=>{if(!pointer)return;if(pointer.kind==='rotate'){state.yaw+=(e.clientX-pointer.lastX)*.012;pointer.lastX=e.clientX;}else{const b=canvas.getBoundingClientRect();pointer.x=e.clientX-b.left;pointer.y=e.clientY-b.top;}requestDraw();});
function releasePeel(e){if(!pointer)return;const p=pointer;pointer=null;if(p.kind==='peel'){const dx=p.x-p.startX,dy=p.y-p.startY;if(Math.hypot(dx,dy)>26)peel(p.id,dx*.65,dy*.65);else $('stage-label').textContent='조각을 잡고 조금 더 길게 당겨 보세요.';}if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);requestDraw();}
canvas.addEventListener('pointerup',releasePeel);canvas.addEventListener('pointercancel',()=>{pointer=null;requestDraw();});canvas.addEventListener('lostpointercapture',()=>{pointer=null;requestDraw();});
let trayDrag=null,suppressClickUntil=0;
$('peel-tray').addEventListener('pointerdown',e=>{const chip=e.target.closest('.peel-chip');if(!chip||state.phase!==1||state.busy||e.button!==0)return;trayDrag={id:Number(chip.dataset.patch),chip,x:e.clientX,y:e.clientY,moved:false,pointerId:e.pointerId};chip.setPointerCapture(e.pointerId);});
$('peel-tray').addEventListener('pointermove',e=>{if(!trayDrag)return;const t=trayDrag;t.moved ||= Math.hypot(e.clientX-t.x,e.clientY-t.y)>6;if(!t.moved)return;const g=$('drag-ghost');g.hidden=false;g.style.left=e.clientX+'px';g.style.top=e.clientY+'px';document.querySelectorAll('.drop-over').forEach(el=>el.classList.remove('drop-over'));document.elementFromPoint(e.clientX,e.clientY)?.closest('.circle-target')?.classList.add('drop-over');});
$('peel-tray').addEventListener('pointerup',e=>{if(!trayDrag)return;const t=trayDrag;trayDrag=null;if(t.moved){suppressClickUntil=performance.now()+350;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('.circle-target');if(target)place(t.id,Number(target.dataset.circle),t.chip);else $('observation').textContent='껍질을 원 위에 놓아 보세요. 놓치더라도 조각은 보관함에 그대로 있어요.';}if(t.chip.hasPointerCapture(e.pointerId))t.chip.releasePointerCapture(e.pointerId);$('drag-ghost').hidden=true;document.querySelectorAll('.drop-over').forEach(el=>el.classList.remove('drop-over'));});
$('peel-tray').addEventListener('click',e=>{if(performance.now()<suppressClickUntil){e.preventDefault();e.stopImmediatePropagation();}},true);
$('peel-tray').addEventListener('pointercancel',()=>{trayDrag=null;$('drag-ghost').hidden=true;document.querySelectorAll('.drop-over').forEach(el=>el.classList.remove('drop-over'));});
$('rotate-mode').onclick=()=>setMode('rotate');$('peel-mode').onclick=()=>setMode('peel');$('rotate-left').onclick=()=>{state.yaw-=Math.PI/4;requestDraw();};$('rotate-right').onclick=()=>{state.yaw+=Math.PI/4;requestDraw();};$('minus').onclick=()=>changeCount(-1);$('plus').onclick=()=>changeCount(1);
$('radius').oninput=e=>{if(state.peeled.size)return;state.radius=Number(e.target.value);resize();update();};
$('start').onclick=()=>{if(!state.started){state.started=true;state.prediction=state.count;state.reason=$('prediction-reason').value.trim();}setPhase(1);setMode('peel');};
$('peel-one').onclick=()=>{const id=nextPatch();if(id!==null){facePatch(id);peel(id);}};
$('peel-strip').onclick=()=>{const id=nextPatch();if(id===null)return;facePatch(id);const lon=id%M.LONGITUDES;for(let b=0;b<M.BANDS;b++)peel(b*M.LONGITUDES+lon,40,60);};
$('place-one').onclick=()=>place(state.tray[0],state.selected,$('peel-tray').firstChild);
$('place-all').onclick=async()=>{if(state.busy||state.phase!==1)return;state.busy=true;update();const revision=state.revision;while(state.tray.length&&revision===state.revision){let target=state.circles.findIndex((a,i)=>i>=state.selected&&a.length<M.PER_CIRCLE);if(target<0)target=state.circles.findIndex(a=>a.length<M.PER_CIRCLE);if(target<0)break;place(state.tray[0],target,$('peel-tray').firstChild);await new Promise(resolve=>setTimeout(resolve,reduced?0:65));}if(revision===state.revision){state.busy=false;update();}};
function saveTrial(){const trial={radius:state.radius,prediction:state.prediction,reason:state.reason,circles:state.count,placed:totalPlaced(),explanation:$('explanation').value.trim()};const previous=state.trials.at(-1);if(previous?.revision===state.revision)Object.assign(previous,trial);else state.trials.push({...trial,revision:state.revision});}
$('discover').onclick=()=>{if(!complete())return;saveTrial();$('comparison').textContent=`처음 예상: 원 ${state.prediction}개 · 관찰 결과: 원 ${state.count}개를 채우고 껍질과 빈 공간이 남지 않았어요.`;$('trial-summary').textContent=state.trials.length>1?`지금까지 반지름 ${state.trials.map(t=>t.radius+' cm').join(', ')}인 구를 실험했어요. 무엇이 달라지고, 무엇이 같았나요?`: '다른 크기의 오렌지에서도 같은 관계가 성립할까요?';setPhase(2);$('discovery-panel').scrollIntoView({behavior:reduced?'instant':'smooth',block:'nearest'});};
$('generalize').onclick=()=>{if(Number($('discovery-number').value)!==4){$('discovery-feedback').textContent='가득 채운 원의 개수를 다시 세어 보세요. 껍질이나 빈 공간이 남았는지도 함께 확인해요.';return;}if(!$('explanation').value.trim()){$('discovery-feedback').textContent='무엇을 관찰했는지 한 문장으로 남겨 보세요. 남은 껍질과 빈 공간을 떠올려도 좋아요.';$('explanation').focus();return;}saveTrial();$('numeric-example').textContent=`이번 구의 반지름은 ${state.radius} cm. 원 한 개의 넓이는 ${state.radius**2}π cm²이고, 구의 겉넓이는 ${4*state.radius**2}π cm² (약 ${M.surfaceArea(state.radius).toFixed(1)} cm²)입니다.`;setPhase(3);$('general-panel').scrollIntoView({behavior:reduced?'instant':'smooth',block:'nearest'});};
function newExperiment(){if(state.busy)return;saveTrial();state.revision++;state.started=false;state.prediction=null;state.reason='';state.peeled.clear();state.tray=[];state.count=3;state.circles=Array.from({length:3},()=>[]);state.selected=0;state.radius=state.radius===5?2:state.radius+1;state.unlocked=0;state.yaw=-.22;flaps=[];$('radius').value=state.radius;$('prediction-reason').value='';$('prediction-reason').readOnly=false;$('start').innerHTML='원 <span id="prediction-count">3</span>개로 예상하고 시작';$('discovery-number').value='';$('explanation').value='';$('discovery-feedback').textContent='';setMode('rotate');setPhase(0);resize();document.querySelector('.question-bar').scrollIntoView({behavior:reduced?'instant':'smooth',block:'start'});}
$('retry-size').onclick=newExperiment;$('new-experiment').onclick=newExperiment;
$('check-challenge').onclick=()=>{const n=Number($('challenge-answer').value);$('challenge-feedback').textContent=n===4?'맞아요. 원의 넓이도 구의 겉넓이도 반지름의 제곱에 따라 커져요. 2 × 2 = 4배입니다.':'반지름이 2배인 원의 넓이를 먼저 생각해 보세요. π × (2r)²에서 2는 어떻게 계산될까요?';};
let recordUrl=null;
$('download').onclick=()=>{saveTrial();const lines=['오렌지 껍질 실험실 · 나의 탐구 기록','제작: 갓세정선생님','',...state.trials.flatMap((t,i)=>[`실험 ${i+1} / 반지름 ${t.radius} cm`,`예상: 원 ${t.prediction}개`,`예상 이유: ${t.reason||'(작성하지 않음)'}`,`관찰: 같은 반지름인 원 ${t.circles}개를 채움`,`나의 설명: ${t.explanation||'(작성하지 않음)'}`,'']), '정리: 구의 겉넓이 = 같은 반지름인 원의 넓이 × 4 = 4πr²','이 모형은 두께 없는 완전한 구를 가정하며, 작은 조각의 넓이를 보존하여 정돈한 표현입니다.'];const text=lines.join('\n');$('record-text').value=text;if(recordUrl)URL.revokeObjectURL(recordUrl);recordUrl=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/plain;charset=utf-8'}));$('record-file').href=recordUrl;$('record-dialog').showModal();};
$('close-record').onclick=()=>$('record-dialog').close();
document.querySelectorAll('.step').forEach((el,i)=>el.onclick=()=>{if(i>state.unlocked||state.busy)return;setPhase(i);if(i!==1)setMode('rotate');});
$('reset').onclick=()=>{$('reset-dialog').showModal();};$('cancel-reset').onclick=()=>$('reset-dialog').close();$('confirm-reset').onclick=()=>{state.revision++;state.trials=[];state.started=false;state.peeled.clear();state.tray=[];state.count=3;state.circles=Array.from({length:3},()=>[]);state.radius=3;state.yaw=-.22;state.selected=0;state.prediction=null;state.reason='';state.busy=false;state.unlocked=0;pointer=null;flaps=[];$('radius').value=3;$('prediction-reason').value='';$('prediction-reason').readOnly=false;$('start').innerHTML='원 <span id="prediction-count">3</span>개로 예상하고 시작';for(const id of ['discovery-number','explanation','challenge-answer'])$(id).value='';$('discovery-feedback').textContent='';$('challenge-feedback').textContent='';$('reset-dialog').close();setMode('rotate');setPhase(0);resize();};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{$('observation').textContent='이 환경에서는 전체 화면을 지원하지 않아요. 브라우저의 확대 기능을 이용해 주세요.';}};
new ResizeObserver(resize).observe(canvas);update();resize();
